// Niche passed directly from orchestrator workflowInputs
const _triggerInput = $input.all()[0]?.json || {};
const _niche = _triggerInput.niche || '';

const raw = $input.all()[0]?.json || {};
// niche comes as direct field OR inside concept object
let concept = raw.concept || raw;
if (typeof concept === 'string') {
  try { concept = JSON.parse(concept); } catch(_) {}
}
const niche = _niche || raw.niche || concept.niche || '';
// Ensure niche propagates into concept
return [{ json: { niche, ...concept, niche } }];

const norm = $('Normalise Image').first().json;
const item = $('Unpack Concept').first().json;
const hasBg = !!($input.first().binary?.data);

const niche    = item.niche    || 'unknown';
const id       = item.id       || Date.now();
const ts       = new Date().toISOString().replace(/[:.]/g, '-');
const fileName = `design_${niche}_${id}_${ts}.png`;

// Return flat record — NO 'concept' string field to avoid character spreading
return [{
  json: {
    niche,
    conceptId:      id,
    title:          item.title          || '',
    phrase:         item.phrase         || '',
    tone:           item.tone           || '',
    source:         item.source         || '',
    targetAudience: item.targetAudience || '',
    sellingAngle:   item.sellingAngle   || '',
    imagePrompt:    item.imagePrompt    || '',
    imageUrl:       norm.resolvedImageUrl || '',
    provider:       norm.provider        || 'unknown',
    fileName,
    generatedAt:    new Date().toISOString()
  }
}];

const item = $input.first().json;
// Ensure niche propagates forward
const niche = item.niche || $('Unpack Concept').first()?.json?.niche || '';
return [{ json: { ...item, niche } }];

const raw = $input.first().json?.data ?? $input.first().json ?? '';
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
const ctx = $('Unpack Concept').first().json;

// Detect quota/error
const isError = text.includes('event: error') || text.includes('quota exceeded') || text.includes('"error"');
if (isError) {
  return [{ json: { ...ctx, ideogramImageUrl: '', ideogramCaption: '', usesFallback: true } }];
}

// Parse success
const match = text.match(/data: (\[.*\])/s);
let imageUrl = '', caption = '';
try {
  const parsed = JSON.parse(match?.[1] || '[]');
  imageUrl = parsed?.[0]?.url || '';
  caption  = JSON.stringify(parsed?.[2] || {});
} catch(_) {}

return [{ json: { ...ctx, ideogramImageUrl: imageUrl, ideogramCaption: caption, usesFallback: !imageUrl } }];

const ctx = $('Unpack Concept').first().json;
const ideogram = $('Parse Ideogram Result').first().json;

// Check which path we came from
const fromPollinations = !!$input.first().binary?.data;
let imageUrl = '';
let provider = 'ideogram';

if (fromPollinations) {
  // Pollinations path — build URL
  const podSuffix = ', isolated on pure white background, bold flat vector illustration, screen print style, 3-5 spot colors max, no gradients, no shadows, no textures, high contrast, print-ready t-shirt graphic, centered composition, professional POD design';
  imageUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent((ctx.imagePrompt || '') + podSuffix) + '?width=1024&height=1024&nologo=true&model=flux&enhance=true';
  provider = 'pollinations-fallback';
} else {
  imageUrl = ideogram.ideogramImageUrl || '';
  provider = 'ideogram';
}

return [{ json: { ...ctx, resolvedImageUrl: imageUrl, ideogramCaption: ideogram.ideogramCaption || '', provider }, binary: $input.first().binary || {} }];
